  if(m[1]!==labels[i]) throw new Error(files[i]+": label mismatch, expected "+labels[i]+" got "+m[1]);
  pop[files[i]]={label:m[1],value:Number.parseInt(m[2],10)};
  console.log(files[i],"->",m[1],"population =",pop[files[i]].value);
