if(!vals.every(v=>Number.isSafeInteger(v)&&v>=0)) throw new Error("non-integer/negative population");
const total=vals.reduce((s,v)=>s+v,0);
console.log("cross-check: 3 distinct populations", JSON.stringify(pop));
console.log("total =",total);
fs.writeFileSync("answer.json", JSON.stringify({total},null,2)+"\n");
'

